const input=$json.body??$json;
const text=v=>v===null||v===undefined?'':String(v).trim();
const bool=v=>typeof v==='boolean'?v:['true','1','yes','on'].includes(text(v).toLowerCase());

const batch_size=Number(input.batch_size??10);
const webhook_base_url=text(input.webhook_base_url||'http://localhost:5678/webhook').replace(/\/+$/,'');
const confirm_dispatch=bool(input.confirm_dispatch);
const errors=[];

if(!Number.isInteger(batch_size)||batch_size<1||batch_size>100){
  errors.push({field:'batch_size',message:'اندازه Batch باید بین 1 و 100 باشد.'});
}
if(!/^https?:\/\/.+/i.test(webhook_base_url)){
  errors.push({field:'webhook_base_url',message:'آدرس Webhook معتبر نیست.'});
}
if(confirm_dispatch!==true){
  errors.push({field:'confirm_dispatch',message:'Dispatch باید تأیید شود.'});
}

return [{json:{
  batch_size,webhook_base_url,
  permission_url:`${webhook_base_url}/clinic/communications/check-permission`,
  delivery_callback_url:`${webhook_base_url}/clinic/communications/messages/delivery-status`,
  confirm_dispatch,
  validation_status:errors.length?'invalid':'valid',
  errors
}}];

const messages=Array.isArray($json.messages)?$json.messages:[];
const cfg=$('Normalize and Validate Dispatch Request').first().json;

if(!messages.length){
  return [{json:{
    has_message:false,
    success:true,
    result:'outbound_queue_empty',
    claimed_count:0
  }}];
}

return messages.map(message=>({json:{
  ...message,
  has_message:true,
  permission_url:cfg.permission_url,
  delivery_callback_url:cfg.delivery_callback_url
}}));

return [{json:{
  ...$json,
  permission_request:{
    clinic_name:$json.clinic_name || '',
    mobile:$json.recipient,
    channel:$json.channel,
    purpose:$json.purpose,
    requested_at:new Date().toISOString(),
    request_reference:$json.request_reference || $json.idempotency_key,
    confirm_check:true
  }
}}];

const original=$('Prepare Dispatch Permission Request').item.json;

return [{json:{
  ...original,
  adapter_request:{
    message_id:original.outbound_message_id,
    idempotency_key:original.idempotency_key,
    channel:original.channel,
    recipient:original.recipient,
    message_type:original.message_type,
    template_code:original.template_code || null,
    language:original.language,
    subject:original.subject || null,
    message_text:original.message_text,
    payload:original.payload || {},
    callback_url:original.delivery_callback_url
  }
}}];

const original=$('Prepare Adapter Request').item.json;
const response=$json??{};
const statusCode=Number(response.statusCode??response.status??200);
const body=response.body??response;
const explicitFailure=
  response.error!==undefined ||
  body?.success===false ||
  statusCode>=400;

const providerId=String(
  body?.provider_message_id ||
  body?.message_id ||
  body?.id ||
  ''
).trim();

return [{json:{
  outbound_message_id:Number(original.outbound_message_id),
  adapter_id:Number(original.adapter_id||0),
  attempt_number:Number(original.attempt_count),
  result:explicitFailure?'failed':'accepted',
  provider_message_id:providerId,
  error_code:explicitFailure?String(body?.error_code||statusCode||'adapter_error'):'',
  error_message:explicitFailure?String(body?.error_message||body?.message||response.error?.message||'Adapter request failed.'):'',
  request_payload_text:JSON.stringify(original.adapter_request||{}),
  response_payload_text:JSON.stringify(response||{}),
  max_attempts:Number(original.max_attempts),
  accepted:!explicitFailure
}}];

const original=$('Prepare Dispatch Permission Request').item.json;
const permission=$json??{};
const deferred=permission.decision==='deferred';
return [{json:{
  outbound_message_id:Number(original.outbound_message_id),
  adapter_id:Number(original.adapter_id||0),
  attempt_number:Number(original.attempt_count),
  result:deferred?'deferred':'blocked',
  provider_message_id:'',
  error_code:String(permission.decision_reason||permission.result||'permission_denied'),
  error_message:deferred?'ارسال به دلیل ترجیحات زمانی بیمار به تعویق افتاد.':'ارسال توسط کنترل رضایت یا ترجیحات بیمار مسدود شد.',
  request_payload_text:JSON.stringify(permission||{}),
  response_payload_text:JSON.stringify(permission||{}),
  max_attempts:Number(original.max_attempts),
  accepted:false
}}];
